\label{rem:bdry-U}
Our assumption on $U$ is slightly stronger than what is required to ensure that the 
Dirichlet problem in $U$ (with continuous boundary data) can be solved 
uniquely \cite[Corollary 10.4.17]{Conway-book-I}. We assume the stronger condition 
to facilitate a convergence theorem for discrete harmonic functions; 
see Theorem \ref{thm2_3}.

\label{lem:finite-Green}
For a finite graph with boundary $(\Lambda, \partial \Lambda)$, we have 
\begin{equation*}
  G_\Lambda(v,w)
  = -A(v,w) + \sum_{e = (e^-,e^+) \in \partial \Lambda} H_\Lambda(v,e) A(e^+,w), 
    \quad v, w \in \Lambda, \end{equation*}
where $H_\Lambda(v,e) = \mathbf{P}^v [ E_{\tau_\Lambda} = e ]$.

Using the burning bijection of Majumdar and Dhar \cite{Majumdar1992}, we have that 
\begin{equation}\begin{split}\label{e:UST-prob} 

  p_\Lambda(0; o)
  &= \frac{|\mathcal{R}(\mathcal{G}^{(g)}_\Lambda)|}{|\mathcal{R}(\mathcal{G}_\Lambda)|}
  = \mathsf{UST}_{\mathcal{G}_\Lambda} [ \text{the edges in $\mathcal{N}^{(g)}$ are not present} ] \\
  &= \frac{1}{\deg(o)} \mathsf{UST}_{\mathcal{G}_\Lambda} [ \text{$o$ is a leaf} ]. \end{split}\end{equation}
The second expression equals $\det(\Delta_{\mathcal{G}^{(g)}_\Lambda})/\det(\Delta_\Lambda)$,
yielding part (i). The third expression can be expressed using the Transfer-Current 
Theorem of Burton and Pemantle \cite{Burton1993}, \cite[Exercise 4.41]{LyonsTrees} as
\begin{equation*}
  \det( I - Y^{(g)}_\Lambda ). \end{equation*}

\label{prop:A-asymp}
Under Assumption \ref{a:graph}, there exist $c_0 = c_0(\mathcal{G})$ and $C_0 = C_0(\mathcal{G})$ 
and a smooth function $U_2$ on the unit circle (also dependent on $\mathcal{G}$), such that 
\begin{equation*}
  A(w,v)
  = \frac{c_0}{\pi} \log |v - w| + C_0 + \frac{U_2((v - w)/|v - w|)}{|v - w|^2} 
    + O \left( |v - w|^{-3} \right), \end{equation*}
as $| v - w | \to \infty$. We have $c_0 = |\det(M)|/ Z_T \sigma^2$.

\label{prop:Y-asymp} 
Suppose that $\mathcal{G}$ satisfies Assumption \ref{a:graph} and that $U$ satisfies 
Assumption \ref{a:U}.
For any $z \in U_\varepsilon$ and edges $e,f$ incident with $z$, we have 
\begin{equation}\begin{split}\label{e:Yeps-asymp} 

 Y_{\varepsilon}(e,f)
 = Y(\hat{e}, \hat{f}) - \varepsilon^2 \frac{c_0}{\pi} J_{e,f} + O(\varepsilon^3), \end{split}\end{equation}
where $c_0$ is the constant from Proposition \ref{prop:A-asymp}, and
where the error term is locally uniform in $z$, when $z$ is viewed as a point in $U$.\\

\label{lem:Javrg}
We have
\begin{equation*}\begin{split} 

 \frac{1}{q} \sum_{r=0}^{q-1} J_{O^r e, O^r f} 
 = \frac{1}{2} \langle e, f \rangle (J_{11} + J_{22})
   + \frac{1}{2} (e_1 f_2 - e_2 f_1) (J_{12} - J_{21})
 = \frac{1}{2} \langle e, f \rangle (J_{11} + J_{22}), \end{split}\end{equation*}
where $\langle e, f \rangle = e_1 f_1 + e_2 f_2$, with $e = e_1 \mathbf{1} + e_2 \mathbf{i}$ (and similarly 
for $f$).

The second equality is immediate from $J_{12} = J_{21}$. To see the first,
from the definition of $J_{e,f}$ in \eqref{e:Jef-def} we have
\begin{equation}\begin{split}\label{e:Jef} 
    J_{e, f} 
  = e_1 f_1 J_{11} + e_2 f_2 J_{22} + e_1 f_2 J_{12} + e_2 f_1 J_{21}. \end{split}\end{equation}
Due to \eqref{e:Jef} we get
\begin{equation*} J_{O^r e, O^r f}
  = (O^r e)_1 (O^r f)_1 J_{11} + (O^r e)_2 (O^r f)_2 J_{22} 
    + (O^r e)_1 (O^r f)_2 J_{12} + (O^r e)_2 (O^r f)_1 J_{21}. \end{equation*}
Summing the coefficient of $J_{11}$ over $r$ we get 
\begin{equation*}\begin{split} 

 &\sum_{r=0}^{q-1} (O^r e)_1 (O^r f)_1 \\
 &\quad= \sum_{r=0}^{q-1} \left[ \cos \left( \frac{r 2 \pi}{q} \right) e_1 
   - \sin \left( \frac{r 2 \pi}{q} \right) e_2 \right]
   \left[ \cos \left( \frac{r 2 \pi}{q} \right) f_1 
   - \sin \left( \frac{r 2 \pi}{q} \right) f_2 \right] \\
 &\quad= \sum_{r=0}^{q-1} \left[ \cos^2 \left( \frac{r 2 \pi}{q}\right) e_1 f_1
   + \sin^2 \left( \frac{r 2 \pi}{q}\right) e_2 f_2 
   - \cos \left( \frac{r 2 \pi}{q} \right) \sin \left( \frac{r 2 \pi}{q} \right) (e_2 f_1 + e_1 f_2) \right]. \end{split}\end{equation*}
Using that when $q \ge 3$, we have
\begin{equation*}\begin{split} 

  \sum_{r=0}^{q-1} \cos^2 \left( \frac{r 2 \pi}{q}\right)
  = \frac{q}{2}, \qquad\quad
  \sum_{r=0}^{q-1} \sin^2 \left( \frac{r 2 \pi}{q}\right)
  = \frac{q}{2}, \qquad\quad
  \sum_{r=0}^{q-1} \frac{1}{2} \sin \left( \frac{r 4 \pi}{q}\right)
  = 0, \end{split}\end{equation*}
we get that the coefficient of $J_{11}$ equals
\begin{equation*}\begin{split} 

 \frac{q}{2} (e_1 f_1 + e_2 f_2) 
 = \frac{q}{2} \langle e,f \rangle. \end{split}\end{equation*}
An analogous computation for the coefficient of $J_{22}$ gives the same expression.

For $J_{12}$, we compute 
\begin{equation*}\begin{split} 

  &\sum_{r=0}^{q-1} (O^r e)_1 (O^r f)_2 \\
  &\quad = \sum_{r=0}^{q-1} \left[ \cos \left( \frac{r 2 \pi}{q} \right) e_1 
   - \sin \left( \frac{r 2 \pi}{q} \right) e_2 \right]
   \left[ \sin \left( \frac{r 2 \pi}{q} \right) f_1 
   + \cos \left( \frac{r 2 \pi}{q} \right) f_2 \right] \\
  &\quad= \sum_{r=0}^{q-1} \left[ \cos^2 \left( \frac{r 2 \pi}{q}\right) e_1 f_2
   - \sin^2 \left( \frac{r 2 \pi}{q}\right) e_2 f_1 
   + \cos \left( \frac{r 2 \pi}{q} \right) \sin \left( \frac{r 2 \pi}{q} \right) (e_1 f_1 - e_2 f_2) \right] \\
  &\quad= \frac{q}{2} (e_1 f_2 - e_2 f_1). \end{split}\end{equation*}
We get the negative of the same expression for the coefficient for $J_{21}$, and this completes the proof.

Recall from Lemma \ref{lem:MD-trick}(ii) that
\[ p_{U_\varepsilon}(0;z)
   = \det(I - Y^{(g)}_{\varepsilon}), \]
where $g$ is an edge incident with $z_\varepsilon$, $\mathcal{N}^{(g)}$ denotes the set of edges incident with $z_\varepsilon$
in $U_\varepsilon$ other than $g$, and 
\[ Y^{(g)}_\varepsilon(e,f)
   = Y_\varepsilon(e,f), \quad e, f \in \mathcal{N}^{(g)}. \]
Write $\mathcal{N}$ for the set of edges incident with $z_\varepsilon$ in $U_\varepsilon$. It will be convenient
to order the set $\{ g \} \cup \mathcal{N}$ in such a way that its cyclic order remains
invariant under the action of the rotation $O$. (For example, by increasing argument of the
endpoint.) Let $M^{(g)}_{e,f}$ denote the minor of $(I - Y)_{e, f \in \mathcal{N}}$ with 
the rows $g,e$ and columns $g,f$ deleted. Then due to Proposition \ref{prop:Y-asymp} we can write
\begin{equation*}\begin{split} 

 p_{U_\varepsilon}(0;z)
 = p(0) + \varepsilon^2 \frac{c_0}{\pi} \sum_{e,f \not= g} 
   J_{e,f}(z) (-1)^{n(e)+n(f)} M^{(g)}_{e,f} + \mathcal{O}(\varepsilon^3), \end{split}\end{equation*}
where $n(e), n(f)$ denotes the indices of $e, f$, respectively, in the fixed ordering.
Since the choice of $g$ is free, we can also write
\begin{equation*}  
\begin{split}
 p_{U_\varepsilon}(0;z)
 &= \frac{1}{q} \sum_{r=0}^{q-1} \det(I - Y^{(O^r g)}_{\varepsilon}) \\
 &= p(0) + \varepsilon^2 \frac{c_0}{\pi} \frac{1}{q} \sum_{r=0}^{q-1} \sum_{e,f \not= g} 
   J_{O^r e, O^r f} (-1)^{n(O^r e) + n(O^r f)} M^{(O^r g)}_{O^r e, O^r f}
   + \mathcal{O}(\varepsilon^3). 
\end{split}
\end{equation*}
It is easy to see that $(-1)^{n(O^r e) + n(O^r f)} = (-1)^{n(e) + n(f)}$, and 
by rotation invariance of the lattice we also have 
$M^{(O^r g)}_{O^r e, O^r f} = M^{(g)}_{e,f}$ (as the matrices differ by a cyclic permutation 
of both the rows and columns). This gives:
\begin{equation}\begin{split}\label{pcorr} 
    &\frac{1}{q} \sum_{r=0}^{q-1} \sum_{e,f \not= g} 
     J_{O^r e, O^r f} (-1)^{n(O^r e) + n(O^r f)} M^{(O^r g)}_{O^r e, O^r f} \\
  &\qquad = \sum_{e,f \not= g} (-1)^{n(e) + n(f)} M^g_{e,f} 
     \left[ \frac{1}{q} \sum_{r=0}^{q-1} J_{O^r e, O^r f} \right]. \end{split}\end{equation}
Adding the $J_{11}$ and $J_{22}$ contributions from Lemma \ref{lem:Javrg}, and substituting 
into \eqref{pcorr}, we have the expression
\begin{equation}\begin{split}\label{e:c_0c_1} 

  \frac{c_0}{\pi} (J_{11} + J_{22}) \frac{1}{2} 
     \sum_{e,f \not= g} (-1)^{n(e)+n(f)} M^{(g)}_{e,f} \langle e,f \rangle
  =: \frac{c_0}{\pi} c_1 (J_{11} + J_{22}). \end{split}\end{equation} 
Putting $f_U = (J_{11} + J_{22})$ and $c_\mathcal{G} := c_0 c_1 / \pi$ completes the proof.

When the boundary of $U$ is smooth, we have the following explicit formula for $f_U$:
\begin{equation}\label{e:fU-formula}
   f_U(z)
   = J_{11}+J_{22}
   = \int_{\partial U} \left[\Re\left(\frac{1}{w-z}\right) \frac{\partial h_U(z,w)}{\partial x}-\Im\left(\frac{1}{w-z}\right) \frac{\partial h_U(z,w)}{\partial y}\right] d\sigma(w), \end{equation}
where $z = (x,y)$, $\sigma$ is the length measure on $\partial U$ and $h_U$ is the density of 
harmonic measure with respect to $\sigma$.

\label{lem:limit-unbounded}
For any $\varepsilon > 0$, we have
\begin{equation}\label{e:limit-unbounded} p_{U,\varepsilon}(0;z)
  = \lim_{R \to \infty} p_{U_R,\varepsilon}(0;z). \end{equation}

\label{thm3_6}
    Let \(U, V \subsetneq \mathbb{C}\) be regions satisfying Assumption \ref{a:U}, and assume that
    $\varphi : U \to V$ is a conformal map. Let $z \in U$ and let $w := \varphi(z) \in V$. 
It holds that 
\begin{equation*}
 f_U(z)
 = |\varphi'(z)|^2 f_V(\varphi(z)). \end{equation*}

(i) Let $e$ be an edge incident with $z_\varepsilon$ in $U_\varepsilon$. By the Transfer-Current Theorem and 
Proposition \ref{prop:Y-asymp}, we have
\begin{equation*}\begin{split} 

 \frac{1}{q} \sum_{r=0}^{q-1} \mathbf{P} [O^r e \in T_{U_\varepsilon}]
 &= \frac{1}{q} \sum_{r=0}^{q-1} Y_\varepsilon(O^r e, O^r e) \\
 &= Y(\hat{e}, \hat{e}) - \varepsilon^2 \frac{1}{q} \sum_{r=0}^{q-1} J_{O^r e, O^r e} + \mathcal{O}(\varepsilon^3). \end{split}\end{equation*}
Due to Lemma \ref{lem:Javrg}, the right hand side equals
\begin{equation}\begin{split}\label{e:fU-expr} 

 Y(\hat{e}, \hat{e}) - \varepsilon^2 \frac{|\hat{e}|^2}{2} (J_{11} + J_{22}) + \mathcal{O}(\varepsilon^3)
 = Y(\hat{e}, \hat{e}) - \varepsilon^2 |\hat{e}|^2 f_U(z) + \mathcal{O}(\varepsilon^3). \end{split}\end{equation}
On the other hand, by monotonicity in the graph, see \cite[Exercise 10.8]{LyonsTrees}, we have
\begin{equation*}\begin{split} 

 \frac{1}{q} \sum_{r=0}^{q-1} \mathbf{P} [O^r e \in T_{U_\varepsilon}]
 \le \frac{1}{q} \sum_{r=0}^{q-1} \mathbf{P} [O^r \hat{e} \in T]
 = \mathbf{P} [\hat{e} \in T]
 = Y(\hat{e}, \hat{e}). \end{split}\end{equation*}
Letting $\varepsilon \to 0$ we get $f_U(z) \ge 0$, proving part (i).

(ii) Due to monotonicity in the graph we have
\begin{equation*}\begin{split} 

 \frac{1}{q} \sum_{r=0}^{q-1} \mathbf{P} [O^r e \in T_{U_\varepsilon}]
 \le \frac{1}{q} \sum_{r=0}^{q-1} \mathbf{P} [O^r e \in T_{V_\varepsilon}], \end{split}\end{equation*}
and the claim follows from \ref{e:fU-expr} letting $\varepsilon \to 0$.

\label{lem:asymp-diff}
There exists $c = c(\mathcal{G},U,z) > 0$ such that for all sufficiently small $\varepsilon > 0$ we have
\begin{equation}\label{e:asymp-diff} p_{U,\varepsilon}(0;z) 
  \ge p(0) + c \varepsilon^2. \end{equation}

Let $\mathcal{N} = \{ e_1, \dots, e_N \}$ be an enumeration of the set of edges incident with $z_\varepsilon$.
Averaging as in the proof of Lemma \ref{lem:monotone}(i), we have that
\[ \frac{1}{q} \sum_{r=0}^{q-1} \mathbf{P} [O^r e_1 \not\in T_{U_\varepsilon}]
   = 1 - Y(\hat{e_1}, \hat{e_1}) + \varepsilon^2 |\hat{e_1}|^2 f_U(z)
     + \mathcal{O}(\varepsilon^3). \]
Hence, for sufficiently small $\varepsilon > 0$, there exists $0 \le r < q$ such that 
\[ \mathbf{P} [O^r e_1 \not\in T_{U_\varepsilon}]
   \ge 1 - Y(\hat{e_1}, \hat{e_1}) + \frac{1}{2} \varepsilon^2 |\hat{e_1}|^2 f_U(z). \]
Without loss of generality, assume that $r=0$, so that
\begin{equation}\label{e:e_1-ineq}
 \mathbf{P} [e_1 \not\in T_{U_\varepsilon}]
   \ge 1 - Y(\hat{e_1}, \hat{e_1}) + \frac{1}{2} \varepsilon^2 |\hat{e_1}|^2 f_U(z). \end{equation}

Let $U_{\varepsilon,j}$ denote the graph obtained from $U_\varepsilon$ by deleting $e_1, \dots, e_j$,
and let $\mathcal{G}_j$ denote the graph obtained similarly from $\mathcal{G}$. 
Then the left hand side of \eqref{e:asymp-diff} equals
\begin{equation}\begin{split}\label{e:T-prob-prod} 

  \prod_{i=1}^{N-1} \mathbf{P} [ e_i \not\in T_{U_\varepsilon} \,|\, e_1, \dots, e_{i-1} \not\in T_{U_\varepsilon} ]. \end{split}\end{equation}
By monotonicity in the graph, see \cite[Lemma 10.3]{LyonsTrees}, for $i = 2, \dots, N-1$, we also have 
\begin{equation*}\begin{split} 

  \mathbf{P} [ e_i \not\in T_{U_\varepsilon} \,|\, e_1, \dots, e_{i-1} \not\in T_{U_\varepsilon} ]
  &= \mathbf{P} [ e_i \not\in T_{U_{\varepsilon,i-1}} ] \\
  &\ge \mathbf{P} [ e_i \not\in T_{\mathcal{G}_{i-1}} ] \\
  &= \mathbf{P} [ e_i \not\in T \,|\, e_1, \dots, e_{i-1} \not\in T ]. \end{split}\end{equation*}
This gives that \eqref{e:T-prob-prod} is at least
\begin{equation*}\begin{split} 

  &\mathbf{P} [ e_1 \not\in T_{U_\varepsilon} ] \prod_{i=2}^{N-1} \mathbf{P} [ e_i \not\in T \,|\, e_1, \dots, e_{i-1} \not\in T ]
  + c' \varepsilon^2 \prod_{i=2}^{N-1} \mathbf{P} [ e_i \not\in T \,|\, e_1, \dots, e_{i-1} \not\in T ] \\
  &\qquad \ge p(0) + c' \varepsilon^2 \frac{p(0)}{\mathbf{P} [e_1 \not\in T]}
  \ge p(0) + c \varepsilon^2. \end{split}\end{equation*}

\label{lem:mart}
For any function $g : \mathcal{V} \to \mathbb{R}$, and for any $v \in \mathcal{V}$, we have that
\begin{equation*}
  g(S_n) - g(S_0) - \sum_{t=0}^{n-1} \frac{1}{\deg(S_t)} \Delta g (S_t), \quad n \ge 0, \end{equation*}
is a martingale under $\mathbf{P}^v$.

\label{lem:lapl}
Let $g : \mathbb{R}^2 \to \mathbb{R}$ have continuous and bounded partial derivatives of order up to $3$.
Then for any $u \in \mathcal{V}$ we have that
\begin{equation*}
  \Delta g(u)
  = \sum_{u' \sim u} (g(u) - g(u'))
  = - \frac{1}{4} \Delta^{(c)} g (u) \sum_{u' \sim u} |u - u'|^2
    + O( \| D^3 g \|_\infty \max_{u'\sim u} |u'-u|^3 ), \end{equation*}
where $\Delta^{(c)} g = (\partial_{11} + \partial_{22}) g$ is the (continuous) Laplacian.

By a Taylor expansion, we have
\begin{equation*}\begin{split} 

  g(u) - g(u')
  = \nabla g \cdot (u - u') - \frac{1}{2} (D^2 g)(u-u',u-u') + O( \| D^3 g \|_\infty 
  \max_{u'\sim u} |u'-u|^3 ). \end{split}\end{equation*}
Due to the rotational symmetry assumed, the sum over $u' \sim u$ of the first term on the right hand side 
vanishes. For the second term, fix some $u'_0 \sim u$ and let $O$ denote rotation by 
an angle $2\pi/q$, where $q = q_u \ge 3$ is the symmetry angle of $\mathcal{G}$ about $u$. 
Let $u'_r - u = O^r (u'_0 - u)$.
Abbreviate $\cos(2\pi r/q_u) =: c(r)$ and $\sin(2\pi r/q_u) =: s(r)$, and 
$\partial_{ij} = \partial_{ij} g$. Then we have
\begin{equation}\begin{split}\label{e:D2g} 

  &D^2 g (u'_r - u, u'_r - u)
  = (u'_r - u)^T \begin{pmatrix}
      \partial_{11} g & \partial_{12} g \\
      \partial_{21} g & \partial_{22} g
  \end{pmatrix} (u'_r - u) \\
  &= (u'_0 - u)^T \begin{pmatrix}
      c(r) & s(r) \\
      -s(r) & c(r)
  \end{pmatrix} \begin{pmatrix}
      \partial_{11} & \partial_{12} \\
      \partial_{12} & \partial_{22}
  \end{pmatrix} \begin{pmatrix}
      c(r) & -s(r) \\
      s(r) & c(r)
  \end{pmatrix} (u'_0 - u) \\
  &= (u'_0 - u)^T \\
  &\quad \begin{pmatrix}
      c^2(r) \partial_{11} + s^2(r) \partial_{22} + 2 s(r) c(r) \partial_{12} 
            & \!\!-c(r) s(r) [ \partial_{11} - \partial_{22} ] + (c^2(r) - s^2(r)) \partial_{12} \\
      -c(r) s(r) [ \partial_{11} - \partial_{22} ] + (c^2(r) - s^2(r)) \partial_{12}
            & \!\!s^2(r) \partial_{11} + c^2(r) \partial_{22} - 2 s(r) c(r) \partial_{12}
  \end{pmatrix} \\
     &\qquad (u'_0 - u). \end{split}\end{equation}
Using the identities 
\begin{align}
\label{e:averaging}
  \sum_{r=0}^{q-1} c^2(r)
  &= \frac{q}{2} & 
  \sum_{r=0}^{q-1} s^2(r)
  &=\frac{q}{2} \\
  \sum_{r=0}^{q-1} c(2r)
  &= 0 & 
  \sum_{r=0}^{q-1} s(2r)
  &= 0, 
\end{align}
the sum of \eqref{e:D2g} over $r = 0, \dots q-1$ equals
\begin{equation*}\begin{split} 

  (u'_0 - u)^T \begin{pmatrix}
      \frac{q}{2} \Delta^{(c)} g & 0 \\
      0 & \frac{q}{2} \Delta^{(c)} g
  \end{pmatrix} (u'_0 - u)
  = \frac{q}{2} \Delta^{(c)} g |u'_0 - u|^2
  = \frac{1}{2} \Delta^{(c)} g \sum_{r=0}^{q-1} |u'_r - u|^2. \end{split}\end{equation*}
Summing over all the orbits of neighbours of $u$ (under the action of $O$) gives the claim.

\label{lem:tau-decay}
There exists a constant $c > 0$ only depending on $\mathcal{G}$ and the fixed vectors $h_1, h_2$ such 
that for all $x, w \in \mathcal{V}$ we have
\begin{equation}\label{e:tau-decay}
  \mathbf{P}^x [ \tau_1 > t]
  \le e^{- c t}. \end{equation}

Due to the rotational symmetry around every vertex of $\mathcal{G}$, we have that
\begin{equation}\begin{split}\label{e:martSw} 

  \mathbf{E}^w [ S_{t+1} - S_t \,|\, \mathcal{F}_t ] = 0. \end{split}\end{equation}
By the same reason, we also have
\begin{equation*}\begin{split} 

  \mathbf{E}^w [ \Re(S_{t+1} - S_t) \Im(S_{t+1} - S_{t}) \,|\, \mathcal{F}_t ]
  = 0. \end{split}\end{equation*}
This implies that
\begin{equation*}\begin{split} 

  &\mathbf{E}^w [ \Re(S_{t+1} - S_0) \Im(S_{t+1} - S_0) \,|\, \mathcal{F}_t ] \\
  &\quad = \Re(S_{t} - S_0) \Im(S_{t} - S_0) 
    + \mathbf{E}^w [ \Re(S_{t+1} - S_t) \Im(S_{t} - S_0) \,|\, \mathcal{F}_t ] \\
  &\qquad\quad + \mathbf{E}^w [ \Re(S_{t} - S_0) \Im(S_{t+1} - S_t) \,|\, \mathcal{F}_t ] \\
  &\quad = \Re(S_{t} - S_0) \Im(S_{t} - S_0), \end{split}\end{equation*}
where we used \eqref{e:martSw}. By the Optional Stopping Theorem, using the decay in Lemma 
\ref{lem:tau-decay},
we get that
\begin{equation*}
  \mathbf{E}^w [ \Re(S_{\tau_1} - S_0) \Im(S_{\tau_1} - S_0) ]
  = 0, \end{equation*}
as claimed.
